import { describe, expect, it } from 'vitest';
import { createCapsule } from '@/lib/context/capsule-service';
import { buildCapsulePromptBlock } from '@/lib/context/context-injection';
import { buildAgentContextPacket } from '@/lib/context/agent-context-packet';
import { createCognitiveCapsule, KnowledgeSchema } from '@/lib/cognitive-capsule/schema';

// These integration tests use a real capsule fixture generated by the service,
// with only its Firestore persistence boundary replaced.
async function fixture() {
  const row = createCognitiveCapsule('diplomacy');
  const actor = { type: 'human', id: 'expert', at: '2026-10-03T00:00:00Z' };
  row.knowledge.push(KnowledgeSchema.parse({ kind: 'languageRule', id: 'prepared', label: 'Conditional openness', scope: ['diplomacy'], expression: 'prepared to consider', language: 'en', meaning: 'An exploratory conditional speech act', domain: 'diplomacy', nonImplications: ['acceptance', 'commitment'], reviewState: 'accepted', provenance: { generatedBy: actor, sourceRefs: [], reviewedBy: actor, reviewedAt: actor.at } }));
  const ref = { id: 'diplomacy', set: async () => {}, collection: () => ({ doc: () => ({ set: async () => {} }) }) };
  const db = { collection: () => ({ doc: () => ({ collection: () => ({ doc: () => ref }) }) }) };
  const capsule = await createCapsule('owner', { capsuleId: 'diplomacy' }, { db: db as never, now: () => new Date('2026-10-03T00:00:00Z') });
  return { ...capsule, cognition: row };
}
describe('Ask cognitive context integration', () => {
  it('puts the reviewed wording rule in the existing Ask inherited context', async () => {
    const c = await fixture();
    const prompt = buildCapsulePromptBlock(c);
    expect(prompt).toContain('prepared to consider');
    expect(prompt).toContain('does_not_establish');
    expect(prompt).toContain('acceptance');
    expect(prompt).toContain('cognitive-context');
  });
  it('binds selected cognitive records into the Agent Context Packet receipt and budget', async () => {
    const c = await fixture();
    const packet = buildAgentContextPacket({ capsule: c, userQuery: 'Has State A accepted?', budgetTier: 'standard', requestTime: '2026-10-03T00:00:00Z' });
    expect(packet.packetText).toContain('prepared to consider');
    expect(packet.cognitiveReceipt?.knowledgeIds).toContain('prepared');
    expect(packet.cognitiveReceipt?.capsuleDigest).toMatch(/^sha256:/);
  });
});
